  'maildrop.cc',
  'getnada.com',
  'temp-mail.org',
  'dispostable.com',
  'mailnesia.com',
  'trashmail.com',
  'spamgourmet.com',
  'mintemail.com',
  'mailcatch.com',
  'mytemp.email',
  'tempinbox.com',
  'fakeinbox.com',
  'emailondeck.com',
]);

// Personal / consumer domains to strip before scoring.
const PERSONAL_DOMAINS = new Set([
  'gmail.com',
  'yahoo.com',
  'yahoo.co.uk',
  'hotmail.com',
  'outlook.com',
  'aol.com',
  'icloud.com',
  'me.com',
  'protonmail.com',
  'proton.me',
  'zoho.com',
  'gmx.com',
  'mail.com',
  'live.com',
  'msn.com',
]);

// Student / academic domains to strip before scoring (anti-ICP Stage 5).
const STUDENT_DOMAINS = new Set([
  'student.edu',
  'university.edu',
  'college.edu',
  'academia.edu',
  'students.edu',
  'alumni.edu',
  'edu',
  'ac.uk',
  'ac.in',
  'edu.au',
  'edu.cn',
  'edu.sg',
  'uni.edu',
]);

// Competitor / out-of-ICP company domains to block (anti-ICP Stage 5).
// NOTE: keep this list current as the competitive set changes.
const COMPETITOR_DOMAINS = new Set([
  'hubspot.com',
  'salesforce.com',
  'pipedrive.com',
  'zoho.com',
  'freshworks.com',
  'intercom.com',
  'drift.com',
  'clearbit.com',
  'clay.com',
  'apollo.io',
]);

// Unsupported jurisdictions (anti-ICP Stage 5).
// Country codes (ISO 3166-1 alpha-2) whose leads are auto-disqualified.
const BLOCKED_JURISDICTIONS = new Set([
  'KP', // North Korea
  'IR', // Iran
  'CU', // Cuba
  'SY', // Syria
  'BY', // Belarus
  'RU', // Russia
  'VE', // Venezuela
  'MM', // Myanmar
  'SD', // Sudan
  'ZW', // Zimbabwe
]);

// Common country names / aliases -> ISO code, so a payload carrying a country
// NAME (e.g. "Russia", "Russian Federation") is blocked just like a code.
// Keys are normalized: lowercase, letters/spaces only. Keep in sync with
// n8n-jurisdiction-check.js (Stage 5 backstop node).
const COUNTRY_NAME_TO_CODE = {
  'russia': 'RU',
  'russian federation': 'RU',
  'rf': 'RU',
  'belarus': 'BY',
  'belorussia': 'BY',
  'iran': 'IR',
  'islamic republic of iran': 'IR',
  'persia': 'IR',
  'north korea': 'KP',
  'democratic peoples republic of korea': 'KP',
  'dprk': 'KP',
  'cuba': 'CU',
  'syria': 'SY',
  'syrian arab republic': 'SY',
  'venezuela': 'VE',
  'bolivarian republic of venezuela': 'VE',
  'myanmar': 'MM',
  'burma': 'MM',
  'myanmar burma': 'MM',
  'sudan': 'SD',
  'zimbabwe': 'ZW',
};

/** Normalize a country name for lookup: lowercase, strip punctuation. */
function normalizeCountryName(name) {
  if (typeof name !== 'string') return '';
  return name.toLowerCase().replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
}

/**
 * Resolve a country signal (ISO code and/or name) against the blocklist.
 * Returns { blocked, code } — code is the ISO alpha-2 code when blocked.
 */
function resolveBlockedCountry(countryCode, countryName) {
  if (typeof countryCode === 'string') {
    const code = countryCode.trim().toUpperCase();
    if (BLOCKED_JURISDICTIONS.has(code)) {
      return { blocked: true, code };
    }
  }
  const normalized = normalizeCountryName(countryName);
  if (normalized && COUNTRY_NAME_TO_CODE[normalized]) {
    const code = COUNTRY_NAME_TO_CODE[normalized];
    if (BLOCKED_JURISDICTIONS.has(code)) {
      return { blocked: true, code };
    }
  }
  return { blocked: false, code: null };
}

// Basic RFC-ish email format check.
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

/**
 * Normalize a string: trim, collapse internal whitespace,
 * and strip control characters / malformed tokens.
 */
function normalizeText(value) {
  if (typeof value !== 'string') return value;
  return value
    .replace(/[\u0000-\u001F\u007F]/g, ' ') // control chars
    .replace(/\s+/g, ' ')                    // collapse whitespace
    .trim();
}

/**
 * Validate and sanitize an email address.
 * Returns { ok, email, domain, reason }.
 */
function sanitizeEmail(email) {
  if (typeof email !== 'string') {
    return { ok: false, email: null, domain: null, reason: 'email_missing' };
  }

  const cleaned = email.trim().toLowerCase();
  if (!EMAIL_REGEX.test(cleaned)) {
    return { ok: false, email: null, domain: null, reason: 'email_invalid_format' };
  }

  const domain = cleaned.split('@')[1].toLowerCase();

  if (TEMP_EMAIL_DOMAINS.has(domain)) {
    return { ok: false, email: cleaned, domain, reason: 'temporary_email_provider' };
  }

  if (PERSONAL_DOMAINS.has(domain)) {
    return { ok: false, email: cleaned, domain, reason: 'personal_domain' };
  }

  // Anti-ICP Stage 5 hard exclusions.
  if (STUDENT_DOMAINS.has(domain) || domain.endsWith('.edu')) {
    return { ok: false, email: cleaned, domain, reason: 'student_domain' };
  }

  if (COMPETITOR_DOMAINS.has(domain)) {
    return { ok: false, email: cleaned, domain, reason: 'competitor_domain' };
  }

  return { ok: true, email: cleaned, domain, reason: null };
}

/**
 * Recursively strip malformed text from string fields in the
 * payload, preserving structure of nested objects/arrays.
 */
function stripMalformedText(value) {
  if (typeof value === 'string') {
    return normalizeText(value);
  }
  if (Array.isArray(value)) {
    return value.map(stripMalformedText);
  }
  if (value && typeof value === 'object') {
    const out = {};
    for (const key of Object.keys(value)) {
      out[key] = stripMalformedText(value[key]);
    }
    return out;
  }
  return value;
}

function stableStringify(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(',')}]`;
  }
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function stableHash(value) {
  let hash = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function firstNonEmptyString(...values) {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) {
      return value.trim();
    }
  }
  return null;
}

function resolveIngestionEventId(raw, lead) {
  const headers = raw && typeof raw.headers === 'object' ? raw.headers : {};
  const existing = firstNonEmptyString(
    lead.event_id,
    lead.eventId,
    lead.ingestion_event_id,
    lead.hookdeck_event_id,
    raw.event_id,
    raw.eventId,
    raw.id,
    raw.hookdeck_event_id,
    headers['x-hookdeck-eventid'],
    headers['x-hookdeck-event-id'],
    headers['x-event-id']
  );
  if (existing) return existing;

  const seed = stableStringify({
    source_type: lead.source_type || raw.source_type || 'inbound',
    submitted_at: lead.submitted_at || lead.timestamp || lead.created_at || raw.timestamp || null,
    payload: lead,
  });
  return `cp_ingest_${stableHash(seed)}`;
}

/**
 * Main entry point for the n8n Code node.
 */

  // Hookdeck / n8n may wrap the payload in an envelope (headers/params/query/body);
  // unwrap if present so we always operate on the lead object itself.
  const raw = $input.first().json;
  const lead = raw.body && typeof raw.body === 'object' ? raw.body : raw;

  // 0. Strip malformed text FIRST — before any gate. Rejected leads (bad email,
  //    blocked jurisdiction) also flow to Log Spam, and control characters
  //    (\u0000 etc.) crash Postgres with 22P05 if they reach the spam_log RPC.
  const strippedLead = stripMalformedText(lead);
  const eventId = resolveIngestionEventId(raw, strippedLead);

  // 1. Sanitize the email next — gate everything else on it.
  const emailCheck = sanitizeEmail(strippedLead.email);

  if (!emailCheck.ok) {
    return {
      json: {
        ...strippedLead,
        sanitized: false,
        reason: emailCheck.reason,
        email: emailCheck.email || null,
        event_id: eventId,
      },
    };
  }

  // Anti-ICP Stage 5: hard-exclude blocked jurisdictions when the payload
  // carries a country signal (ISO code or name) — reject at the door so we
  // never spend verification/enrichment credits on them.
  const jurisdiction = resolveBlockedCountry(strippedLead.country_code, strippedLead.country);
  if (jurisdiction.blocked) {
    return {
      json: {
        ...strippedLead,
        sanitized: false,
        reason: 'blocked_jurisdiction',
        email: emailCheck.email || null,
        event_id: eventId,
        country_code: jurisdiction.code,
      },
    };
  }

  // 2. Pass branch: lead is already stripped (step 0). Re-apply the validated
  //    email (normalized + lowercased).
  const sanitizedLead = { ...strippedLead, event_id: eventId };
  sanitizedLead.email = emailCheck.email;

  return {
    json: {
      ...sanitizedLead,
      sanitized: true,
      email_domain: emailCheck.domain,
    },
  };

const dedupRaw = $('Dedup: Get or Create Lead').first().json;
const dedup = Array.isArray(dedupRaw) ? (dedupRaw[0] || {}) : (dedupRaw || {});
const sanitized = $('Sanitize Lead').first().json || {};

return [{
  ...sanitized,
  ...dedup,
}];

const normalized = $('Normalize Lead Context').first().json || {};

return [{
  ...normalized,
  timeline_logged: true,
}];

/**
 * ============================================
 * n8n Code Node — Stage 2b: Parse Email Verification Result
 * ============================================
 * Paste this into an n8n "Code" node (JavaScript mode).
 *
 * Purpose:
 *   Normalize the verification provider's response into a single
 *   { deliverable, verdict } decision. Provider-agnostic — handles
 *   Emailable (state), Abstract (deliverability), Hunter (data.result),
 *   and ZeroBounce (status) shapes.
 *
 *   deliverable = true ONLY for confirmed-deliverable verdicts:
 *     Emailable:  state === "deliverable"
 *     Abstract:   deliverability === "DELIVERABLE" && not disposable
 *     Hunter:     result === "deliverable"
 *     ZeroBounce: status === "valid"
 *   catch-all / risky / unknown / disposable -> NOT deliverable
 *   (conservative by design for CRM hygiene).
 *
 * Input:   $json = provider response
 * Output:  [{ deliverable: boolean, verdict: string }]
 * ============================================
 */

/** Normalize an Emailable / Abstract / Hunter / ZeroBounce verification response. */
function parseVerifyResponse(raw) {
  const data = (raw && (raw.data || raw)) || {};

  // Emailable: { state: "deliverable"|"undeliverable"|"risky"|"unknown", reason }
  const state = String(data.state || '').toLowerCase();

  // Abstract: { deliverability: "DELIVERABLE"|"UNDELIVERABLE"|"UNKNOWN"|"RISKY", is_disposable_email: bool, ... }
  const deliverability = String(data.deliverability || '').toLowerCase();

  // Hunter:   { data: { status, result } }
  // ZeroBounce: { status, sub_status }
  const status = String(data.status || '').toLowerCase();
  const result = String(data.result || '').toLowerCase();

  // Mailboxlayer: { format_valid, mx_found, smtp_check, catch_all, disposable, ... }
  const smtpOk = data.smtp_check === true || data.smtp_check === 'true';

  const deliverable =
    state === 'deliverable' ||
    (deliverability === 'deliverable' && !data.is_disposable_email) ||
    result === 'deliverable' ||
    status === 'valid' ||
    (data.format_valid === true && smtpOk && data.catch_all !== true && !data.disposable);

  // verdict is debug info; the deliverable boolean is the decision.
  const verdict = deliverable
    ? 'deliverable'
    : state || deliverability || result || status || 'unknown';

  return { deliverable, verdict };
}


  const raw = $input.first().json;
  const parsed = parseVerifyResponse(raw);

  return [{ deliverable: parsed.deliverable, verdict: parsed.verdict }];

/**
 * ============================================
 * n8n Code Node — Stage 4: Merge Enrichment Into Firmographics
 * ============================================
 * Paste this into an n8n "Code" node (JavaScript mode).
 *
 * Purpose:
 *   Merge company enrichment data (Apollo organization response) into the
 *   lead's firmographics before Gemini scoring. Provider-agnostic: when the
 *   input carries an `organization` object the new fields win; otherwise
 *   the sanitizer's firmographics pass through unchanged (enrichment OFF).
 *
 * Business rules (see .clinerules):
 *   * Enrichment runs only for NEW + deliverable leads (the workflow gates
 *     it after verification) — never wastes credits on duplicates/bounces.
 *   * Enrichment never removes existing data — it only fills gaps.
 *
 * Reads:
 *   $input  = Call Enrich API response { organization: {...} }
 *             OR pass-through items (enrichment disabled path)
 *   $('Sanitize Lead')            -> { firmographics }   (base data)
 *   $('Dedup: Get or Create Lead') -> { lead_id }
 *
 * Output (to "Score Lead (Gemini)"):
 *   [{ lead_id, firmographics }]   (merged, or unchanged when no org data)
 * ============================================
 */

/**
 * Merge Apollo organization data into base firmographics.
 * Organization fields win when present; base data is never dropped.
 */
function mergeEnrichment(inputJson, baseFirmographics) {
  const org = inputJson && inputJson.organization;
  if (!org) {
    return baseFirmographics || {};
  }

  return {
    ...(baseFirmographics || {}),
    industry: org.industry || (baseFirmographics || {}).industry,
    employees: org.estimated_num_employees || (baseFirmographics || {}).employees,
    country: org.country || (baseFirmographics || {}).country,
    city: org.city || (baseFirmographics || {}).city,
    enriched_by: 'apollo',
  };
}


  const input = $input.first().json;
  const sanitized = $('Sanitize Lead').first().json;
  const base = (sanitized && sanitized.firmographics) || {};
  const firmographics = mergeEnrichment(input, base);
  const leadId = $('Dedup: Get or Create Lead').first().json.lead_id;

  return [{ lead_id: leadId, firmographics }];

/**
 * ============================================
 * n8n Code Node — Stage 5: Blocked-Jurisdiction Check
 * ============================================
 * Paste this into an n8n "Code" node (JavaScript mode).
 *
 * Purpose:
 *   Enforce the anti-ICP hard-exclusion list for unsupported jurisdictions.
 *   Runs AFTER Stage 4 enrichment (which may reveal the country via the
 *   org's firmographics — Apollo returns country as a NAME, e.g. "Russia"),
 *   and BEFORE Stage 6 scoring. A blocked lead is never scored/CRM'd.
 *
 * Business rules (see .clinerules):
 *   * Blocked jurisdictions: KP, IR, CU, SY, BY, RU, VE, MM, SD, ZW.
 *   * Accepts ISO 3166-1 alpha-2 country_code OR a common country name
 *     (Apollo's name form) — both are normalized to the ISO code.
 *   * This node is the post-enrichment backstop; the sanitizer (Stage 1)
 *     already rejects payload-provided country signals at the door.
 *
 * Reads:
 *   $('Parse Enrichment')           -> { lead_id, firmographics }
 *   $('Dedup: Get or Create Lead')  -> { lead_id }
 *
 * Outputs (to "Jurisdiction OK?" IF node):
 *   [{ lead_id, jurisdiction_blocked, country_code }]
 * ============================================
 */

// Unsupported jurisdictions (ISO 3166-1 alpha-2) whose leads are auto-disqualified.
const BLOCKED_JURISDICTIONS = new Set([
  'KP', // North Korea
  'IR', // Iran
  'CU', // Cuba
  'SY', // Syria
  'BY', // Belarus
  'RU', // Russia
  'VE', // Venezuela
  'MM', // Myanmar
  'SD', // Sudan
  'ZW', // Zimbabwe
]);

// Common country names / aliases -> ISO code, for the name-form country
// field that enrichment providers (Apollo) return. Keys are normalized:
// lowercase, letters/spaces only.
const COUNTRY_NAME_TO_CODE = {
  'russia': 'RU',
  'russian federation': 'RU',
  'rf': 'RU',
  'belarus': 'BY',
  'belorussia': 'BY',
  'iran': 'IR',
  'islamic republic of iran': 'IR',
  'persia': 'IR',
  'north korea': 'KP',
  'democratic peoples republic of korea': 'KP',
  'dprk': 'KP',
  'cuba': 'CU',
  'syria': 'SY',
  'syrian arab republic': 'SY',
  'venezuela': 'VE',
  'bolivarian republic of venezuela': 'VE',
  'myanmar': 'MM',
  'burma': 'MM',
  'myanmar burma': 'MM',
  'sudan': 'SD',
  'zimbabwe': 'ZW',
};

/** Normalize a country name for lookup: lowercase, strip punctuation. */
function normalizeCountryName(name) {
  if (typeof name !== 'string') return '';
  return name.toLowerCase().replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
}

/**
 * Resolve a country signal (ISO code and/or name) against the blocklist.
 * Returns { blocked, code } — code is the ISO alpha-2 code when blocked.
 */
function resolveBlockedCountry(countryCode, countryName) {
  if (typeof countryCode === 'string') {
    const code = countryCode.trim().toUpperCase();
    if (BLOCKED_JURISDICTIONS.has(code)) {
      return { blocked: true, code };
    }
  }
  const normalized = normalizeCountryName(countryName);
  if (normalized && COUNTRY_NAME_TO_CODE[normalized]) {
    const code = COUNTRY_NAME_TO_CODE[normalized];
    if (BLOCKED_JURISDICTIONS.has(code)) {
      return { blocked: true, code };
    }
  }
  return { blocked: false, code: null };
}


  const enriched = $('Parse Enrichment').first().json;
  const firmographics = (enriched && enriched.firmographics) || {};
  const leadId = $('Dedup: Get or Create Lead').first().json.lead_id;

  const res = resolveBlockedCountry(firmographics.country_code, firmographics.country);

  return [{
    lead_id: leadId,
